from pathlib import Path
from openpyxl import load_workbook
import re
def show(row):
 return ' '.join(f'{c.coordinate}:{c.value"'!r}/{c.data_type}'"' for c in row if c.value is not None)
for p in sorted(Path('.').glob('*/*/*.xlsx')):
 if not any(x in str(p) for x in ('sanko2','056','pref_card','eisei')):continue
 w=load_workbook(p,data_only=True)
 print('\\n',p)
 for s in w:
  if 'sanko' in p.name:
   if not re.search(r'2\\D*15',s.title): continue
   rows=list(s.rows); print(s.title,s.max_row,*map(show,rows[:8]+rows[-8:]),sep='\\n');print('numeric strings',[(c.coordinate,c.value) for row in rows for c in row if isinstance(c.value,str) and re.fullmatch(r'[\\d,]+',c.value.strip())])
  elif '056' in p.name:
   for row in list(s.rows)[:21]+list(s.rows)[-4:]:
    if ('R02' in p.name or 'R01' in p.name or 'R06' in p.name):print(show(row)[:3300])
   print(s.title,[(c.coordinate,c.value) for row in list(s.rows)[:25] for c in row if isinstance(c.value,str) and re.search('配偶|交際|解決|予備',c.value)])
  elif 'pref_card' in p.name:
   if '沖縄' in s.title:
    print(s.title,*[show(row) for row in s.rows if any(re.search('実質収支|単年度収支|実\\s*質\\s*収\\s*支|単\\s*年\\s*度\\s*収\\s*支',str(c.value)) for c in row)],sep='\\n')
  else:
   print(s.title,s.max_row,s.max_column)
   for row in s.rows:
    if any(any(x in str(c.value) for x in ('1,367','1,378','措置患者','第２表－１','第2表-1')) or c.value in (1367,1378) for c in row):print(show(row)[:2500])
